"""
Auto-calibration for the floor tracker (used by build_floor_tracker.py and update_patch.py).

add_autocalibration(ft) adds to a floor_tracker COMP (safe to call again):
  * Floor page: Auto Calibrate (pulse), Calibration Status, plus internal state parameters;
  * calib_markers -- Movie File In showing the ArUco marker pattern (generated by the helper).

Projector page: Output Warp (Auto squares the image up on the floor using Camera Tilt / FOV;
drag Camera Tilt until the projection looks rectangular -- it updates live), Warp Corners (set
automatically, used by the output_warp stage in your output).

Pressing Auto Calibrate: the pattern is shown (Calibrating = on -- route calib_markers into
your output, which integrate_roots.py does for /container1 automatically), the helper finds
the markers in the camera, solves camera -> content, and the four corners are filled in.
"""


def _add(page, kind, name, label, default):
	p = getattr(page, 'append' + kind)(name, label=label)[0]
	p.default = p.val = default
	return p


def add_autocalibration(ft):
	cam = ft.par.Cornerblx.page            # the Floor page
	if not hasattr(ft.par, 'Autocalibrate'):
		cam.appendPulse('Autocalibrate', label='Auto Calibrate')
		_add(cam, 'Str', 'Calibstatus', 'Calibration Status', 'not calibrated yet')
		_add(cam, 'Toggle', 'Calibrating', 'Calibrating (showing markers)', False)
		_add(cam, 'Int', 'Calibrequest', 'Calibration Request (internal)', 0)
		_add(cam, 'Str', 'Markerfile', 'Marker Pattern File', '/tmp/floor_track_markers.png')
		_add(cam, 'Str', 'Calibfile', 'Calibration Result File', '/tmp/floor_track_calib.json')
	if not hasattr(ft.par, 'Warpmode'):
		pg = ft.appendCustomPage('Projector')
		p = pg.appendMenu('Warpmode', label='Output Warp')[0]
		p.menuNames, p.menuLabels = ['auto', 'off'], ['Auto (square up on the floor)', 'Off (full projector image)']
		p.default = p.val = 'auto'
		_add(pg, 'Float', 'Cameratilt', 'Camera Tilt (deg from straight down)', 35.0).normMax = 80
		_add(pg, 'Float', 'Camerafov', 'Camera FOV (horizontal deg)', 70.0).normMax = 120
		for k, (x, y) in (('bl', (0, 0)), ('br', (1, 0)), ('tr', (1, 1)), ('tl', (0, 1))):
			for par, v in zip(pg.appendXY('Projcorner' + k, label='Warp Corner ' + k.upper() + ' (auto)'), (x, y)):
				par.default = par.val = v
	if not hasattr(ft.par, 'Constantsize'):
		_add(ft.par.Warpmode.page, 'Toggle', 'Constantsize', 'Constant Circle Size (on the floor)', True)
	m = ft.op('calib_markers')
	if m is None:
		m = ft.create(moviefileinTOP, 'calib_markers')
		pattern = ft.op('calib_pattern')
		if pattern is not None:
			m.nodeX, m.nodeY = pattern.nodeX + 200, pattern.nodeY
	m.par.file.expr = 'parent().par.Markerfile'
	try:
		ft.op('pulses').module.make_markers(ft)
	except Exception as e:
		print('autocal: could not generate the marker pattern yet ({})'.format(e))
	return m
